  template: `
    @if (page(); as page) {
      <main id="main-content" tabindex="-1" class="wizard pb-16">
        @let receipt = page.step === 'summary' ? payment.receipt(page.country) : null;
        @let plan = summaryPlan(page);
        <app-wizard-progress [step]="receipt ? 4 : page.step === 'details' ? 1 : plan ? 3 : 2" />
        @if (page.step === 'details') {
          <div class="step-heading mt-6 mb-3.5 lg:my-4 lg:text-center">
            <h1 tabindex="-1" id="screen-heading">Datos para cotizar</h1>
          </div>
        }
        @let state = store.state();
        @if (receipt) {
          <section
            class="status-panel mx-auto mt-6 max-w-[38rem] rounded-lg border border-divider bg-paper p-5 text-center sm:mt-12 sm:p-8"
          >
            <span
              aria-hidden="true"
              class="mx-auto inline-grid size-10 place-items-center rounded-full border border-success bg-success-tint text-success"
            >
              <svg
                viewBox="0 0 24 24"
                class="size-6"
                fill="none"
                stroke="currentColor"
                stroke-width="2"
                stroke-linecap="round"
                stroke-linejoin="round"
              >
                <path d="m5 12 4 4L19 6" />
              </svg>
            </span>
            <h1 id="receipt-heading" tabindex="-1" class="mt-3">Pago aprobado</h1>
            <dl class="mt-5 rounded-lg bg-context px-3 py-4 text-link">
              <dt class="text-sm font-bold">Número de cotización</dt>
              <dd class="mt-1 text-2xl font-bold [overflow-wrap:anywhere]">{{ receipt }}</dd>
            </dl>
          </section>
        } @else if (state.phase === 'ready' && state.country === page.country) {
          @if (page.step === 'details') {
            <app-details-form [configuration]="state.form" (complete)="advance(page.country)" />
          } @else if (plan) {
            <app-quote-summary [country]="page.country" [form]="state.form" [plan]="plan" />
          } @else if (store.canContinue(page.country)) {
            <app-plan-list [country]="page.country" (complete)="openSummary(page.country)" />
          }
        } @else if (state.phase === 'unavailable' && state.country === page.country) {
          <section
            class="status-panel rounded-lg border border-error bg-error-tint px-4 py-5 text-error sm:px-6"
          >
            <h2 id="configuration-error" tabindex="-1">Formulario no disponible</h2>
            <p class="mt-2 text-sm text-error">
              No pudimos cargar el formulario. Intenta de nuevo.
            </p>
            <button
              class="primary-button mt-4 inline-flex min-h-12 items-center justify-center rounded-md bg-action px-6 text-base font-bold text-white hover:bg-action-hover active:bg-action-hover"
              type="button"
              (click)="store.load(page.country, true)"
            >
              Reintentar
            </button>
          </section>
        } @else {
          <section class="status-panel rounded-lg border border-divider bg-paper px-4 py-5 sm:px-6">
            <h2>Cargando el formulario…</h2>
            <p class="mt-2 text-sm text-secondary">
<h1 id="summary-heading" tabindex="-1" class="my-6 text-center lg:mt-5 lg:mb-9">
  Revisa tu cotización
</h1>
<div class="grid items-start gap-5 lg:grid-cols-[minmax(0,0.93fr)_minmax(0,1fr)] lg:gap-8">
  <section
    aria-labelledby="review-heading"
    class="min-w-0 rounded-lg border border-divider bg-paper px-4 py-3 sm:px-5"
  >
    <div class="flex flex-wrap items-center justify-between gap-x-3">
      <h2 id="review-heading" class="text-2xl">Titular y vehículo</h2>
      <a
        class="inline-flex min-h-11 items-center text-sm font-bold text-link underline underline-offset-4"
        [routerLink]="['/', country(), 'quote', 'details']"
        >Editar datos</a
      >
    </div>
    <dl>
      @for (row of rows(); track row.id) {
        <div
          class="grid grid-cols-[minmax(0,1fr)_minmax(0,1fr)] gap-3 border-t border-divider py-3 text-sm [overflow-wrap:anywhere]"
        >
          <dt class="text-secondary">{{ row.label }}</dt>
          <dd class="font-bold">{{ row.value }}</dd>
        </div>
      }
    </dl>
  </section>

  <div class="min-w-0">
    <section
      aria-labelledby="selected-plan-heading"
      class="rounded-lg bg-context px-5 pb-6 pt-2 [overflow-wrap:anywhere]"
    >
      <div class="flex flex-wrap items-center justify-between gap-x-3">
        <p class="text-sm font-bold text-secondary">Plan elegido</p>
        <a
          class="inline-flex min-h-11 items-center text-sm font-bold text-link underline underline-offset-4"
          [routerLink]="['/', country(), 'quote', 'plans']"
          >Cambiar plan</a
        >
      </div>
      <h2 id="selected-plan-heading">{{ plan().name }}</h2>
      <p class="mt-3 text-sm font-bold text-secondary">Precio final</p>
      <p class="mt-1 text-[1.75rem] leading-tight font-bold text-link">{{ price() }}</p>
    </section>

    @let phase = payment.phase();
    <section class="mt-5" aria-labelledby="terms-heading">
      <h2 id="terms-heading" tabindex="-1">Términos y condiciones</h2>
      @if (phase === 'unavailable') {
        <p role="alert" class="mt-3 rounded-md bg-error-tint px-3 py-3 font-bold text-error">
          No pudimos cargar los términos.
        </p>
        <button
          id="terms-retry"
          type="button"
          class="mt-3 min-h-11 rounded-md border border-control bg-paper px-4 font-bold text-link"
          (click)="retryTerms($event)"
        >
          Reintentar carga
        </button>
      } @else if (phase === 'loading') {
        <p class="mt-3 rounded-md bg-context px-3 py-3 text-secondary">Cargando términos…</p>
      } @else if (payment.terms(); as terms) {
        @if (payment.termsChanged()) {
          <p role="alert" class="mt-3 rounded-md bg-context px-3 py-3 font-bold text-link">
            Los términos cambiaron. Léelos y acéptalos para continuar.
          </p>
        }
        <p class="mt-3 leading-relaxed whitespace-pre-wrap text-secondary [overflow-wrap:anywhere]">
          {{ terms.text }}
        </p>
        <label class="inline-flex min-h-11 items-center gap-2 text-sm">
          <input
            type="checkbox"
            class="size-5 shrink-0 accent-link"
            [checked]="payment.accepted()"
            [disabled]="payment.busy()"
            (change)="updateConsent($event)"
          />
          Acepto los términos y condiciones
        </label>
      }
    </section>

    <div class="mt-3 border-t border-divider pt-3">
      @if (payment.paymentRejected()) {
        <div role="alert" class="mb-3 rounded-md bg-error-tint px-3 py-3 text-error">
          <p class="font-bold">Pago rechazado.</p>
        </div>
      }
      <fieldset>
        <legend class="font-bold">Resultado de prueba</legend>
        <div class="flex flex-wrap gap-x-6">
          <label class="inline-flex min-h-11 items-center gap-2 text-sm font-bold">
            <input
              type="radio"
              name="payment-outcome"
              value="approved"
              class="size-5 accent-link"
              [checked]="outcome() === 'approved'"
              (change)="outcome.set('approved')"
            />
            Aprobado
          </label>
          <label class="inline-flex min-h-11 items-center gap-2 text-sm font-bold">
            <input
              type="radio"
              name="payment-outcome"
              value="rejected"
              class="size-5 accent-link"
              [checked]="outcome() === 'rejected'"
              (change)="outcome.set('rejected')"
            />
            Rechazado
          </label>
        </div>
      </fieldset>
      <p role="status" class="sr-only">{{ status() }}</p>
      @let payHint =
        payment.busy()
          ? status()
          : phase === 'ready' && !payment.accepted()
            ? 'Acepta los términos para continuar.'
            : '';
      @if (payHint) {
        <p id="payment-hint" class="mb-2 text-sm text-secondary">{{ payHint }}</p>
      }
      <button
        type="button"
        class="primary-button min-h-12 w-full rounded-md bg-action px-6 font-bold text-white hover:bg-action-hover aria-disabled:cursor-not-allowed aria-disabled:bg-divider aria-disabled:text-secondary sm:w-auto"
        [attr.aria-disabled]="!payment.canPay()"
        [attr.aria-describedby]="payHint ? 'payment-hint' : null"
        (click)="pay($event)"
      >
        Pagar
      </button>
    </div>
  </div>
</div>
@import 'tailwindcss';

@theme {
  --color-canvas: #f5f7fc;
  --color-paper: #fff;
  --color-context: #eaf0ff;
  --color-ink: #15243b;
  --color-secondary: #344763;
  --color-muted: #405575;
  --color-action: #2e6df6;
  --color-action-hover: #215bcc;
  --color-link: #1748af;
  --color-control: #586d91;
  --color-divider: #ccd8ee;
  --color-focus: #1746b4;
  --color-success: #1f5b39;
  --color-success-tint: #e8f5ec;
  --color-error: #9e2f26;
  --color-error-tint: #fff2ef;
  --font-heading: Georgia, 'Times New Roman', serif;
  --font-interface: Arial, system-ui, sans-serif;
}

@layer base {
  html {
    scroll-padding-block: 1.5rem;
  }
  body {
    @apply min-h-screen bg-canvas font-interface text-ink;
  }
  h1,
  h2 {
    @apply font-heading font-normal;
  }
  h1 {
    font-size: clamp(2rem, 5vw, 3rem);
    line-height: 1.15;
    text-wrap: balance;
  }
  h2 {
    @apply text-[1.75rem] leading-tight;
  }
  :focus-visible {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
  }
  [tabindex='-1']:focus:not(:focus-visible) {
    outline: none;
  }
}

/* Content-sized lanes and interaction details stay custom; component layout uses template utilities. */
.shell {
  width: min(100% - 2.5rem, 68rem);
  margin-inline: auto;
}
.wizard {
  width: min(100% - 2.5rem, 58rem);
  margin-inline: auto;
}
.details {
  max-width: 44.5rem;
  margin-inline: auto;
}
.status-panel {
  width: min(100%, 44.5rem);
  margin-inline: auto;
}
.field label,
.field-help,
.field-error {
  overflow-wrap: anywhere;
}
.field select:has(option:checked:disabled) {
  color: var(--color-muted);
}
.field.has-error :is(input, select) {
  border-color: var(--color-error);
  box-shadow: inset 0 0 0 1px var(--color-error);
}
.primary-button {
  transition: background-color 120ms;
}

@media (min-width: 48rem) {
  .check-field {
    grid-column: 1 / -1;
  }
}

@media (min-width: 64rem) {
  .wizard-progress li:not(:last-child)::after {
    content: '';
    display: block;
    width: 3.5rem;
    height: 1px;
    margin-inline-start: 1rem;
    background: var(--color-divider);
  }
}

@media (prefers-reduced-motion: reduce) {
  .primary-button {
    transition: none;
  }
}

